const room=window.room={running:false,calm:0,time:45000};
new p5(p=>{
 let field,letters,kind=Math.floor(Math.random()*5),phase=Math.random()*90,t=0,lastLetters=-1,cols,rows,values;
 const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz',roman=['XII','I','II','III','IV','V','VI','VII','VIII','IX','X','XI'];
 const palette=[[255,105,126],[255,155,117],[250,211,130],[213,218,143],[91,186,165],[111,175,183],[175,150,191]];
 function setupLayers(){cols=Math.ceil(p.width/10);rows=Math.ceil(p.height/12);values=new Float32Array(cols*rows);field=p.createImage(cols,rows);letters=p.createGraphics(p.width,p.height);letters.pixelDensity(Math.min(devicePixelRatio||1,2));letters.textFont('monospace');letters.textSize(7);letters.noStroke();}
 p.setup=()=>{p.createCanvas(innerWidth,innerHeight).parent('art');p.pixelDensity(Math.min(devicePixelRatio||1,2));p.frameRate(30);p.noiseDetail(2,.5);setupLayers();addEventListener('keydown',e=>{if(e.repeat)return;if(e.code==='Space'){e.preventDefault();room.running=!room.running}if(e.code==='Digit1'||e.code==='Numpad1'){e.preventDefault();window.toggleCamera?.()}})};
 p.windowResized=()=>{p.resizeCanvas(innerWidth,innerHeight);setupLayers()};
 function renderField(){let c=room.calm;field.loadPixels();for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let u=x/cols,v=y/rows,a=p.noise(u*2+t*.12+phase,v*2-t*.1),b=p.noise(u*2+7-t*.09,v*2+t*.08),n=p.noise(u*2.6+a*2,v*2.6+b*2,t*.16);let gray=p.constrain((n-.32)*2.6,0,1),k=p.constrain((v*.75+u*.12+(n-.5)*1.4)*6,0,5.999),lo=Math.floor(k),f=k-lo;values[x+y*cols]=n;let i=(x+y*cols)*4;for(let ch=0;ch<3;ch++)field.pixels[i+ch]=p.lerp(12+gray*235,p.lerp(palette[lo][ch],palette[lo+1][ch],f),c);field.pixels[i+3]=255}field.updatePixels();}
 function renderLetters(){letters.clear();let c=room.calm,step=Math.floor(t*7);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let n=values[x+y*cols],idx=(x*17+y*31+Math.floor(n*79)+step)%alphabet.length;letters.fill(n>.48?0:255,p.lerp(34,19,c));letters.text(alphabet[idx],x*10,y*12+8)}}
 function outlineText(text,x,y,size,font='monospace'){let ctx=p.drawingContext;ctx.font=`${size}px ${font}`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineWidth=size>60?2.8:1.2;ctx.strokeText(text,x,y)}
 function clock(){let r=Math.min(p.width*.34,p.height*.32);p.push();p.translate(p.width/2,p.height/2);p.blendMode(p.DIFFERENCE);p.stroke(255);p.noFill();p.strokeWeight(3);p.drawingContext.strokeStyle='#fff';if(kind===3||kind===4){let s=Math.floor(room.time),hh=Math.floor(s/3600)%24,mm=Math.floor(s/60)%60,ss=s%60,str=[hh,mm,...(kind===4?[ss]:[])].map(v=>String(v).padStart(2,'0')).join(':');outlineText(str,0,0,Math.min(r*.68,p.width/(str.length*.68)));p.strokeWeight(1.5);p.line(-r,r*.38,r,r*.38)}else{p.circle(0,0,r*2);p.strokeWeight(1);p.circle(0,0,r*2+12);for(let i=0;i<60;i++){let a=i*p.TWO_PI/60-p.HALF_PI;p.strokeWeight(i%5?1.2:2.7);p.line(Math.cos(a)*r*.94,Math.sin(a)*r*.94,Math.cos(a)*r*(i%5?.91:.86),Math.sin(a)*r*(i%5?.91:.86))}if(kind!==2)for(let i=0;i<12;i++){let a=i*p.TWO_PI/12-p.HALF_PI;outlineText(kind===1?roman[i]:String(i||12),Math.cos(a)*r*.73,Math.sin(a)*r*.73,r*.12,kind===1?'Georgia':'monospace')}let hour=room.time/43200*p.TWO_PI-p.HALF_PI,min=room.time/3600*p.TWO_PI-p.HALF_PI,sec=room.time/60*p.TWO_PI-p.HALF_PI;p.strokeWeight(6);p.line(0,0,Math.cos(hour)*r*.47,Math.sin(hour)*r*.47);p.strokeWeight(4);p.line(0,0,Math.cos(min)*r*.72,Math.sin(min)*r*.72);p.strokeWeight(1.5);p.line(-Math.cos(sec)*r*.14,-Math.sin(sec)*r*.14,Math.cos(sec)*r*.83,Math.sin(sec)*r*.83);p.circle(0,0,12)}p.pop();p.blendMode(p.BLEND)}
 p.draw=()=>{let dt=Math.min(p.deltaTime/1000,.1);room.calm=p.lerp(room.calm,room.running?1:0,1-Math.exp(-dt*1.7));if(room.running)room.time+=dt;t+=dt*p.lerp(1.05,.12,room.calm);renderField();p.image(field,0,0,p.width,p.height);if(p.frameCount%3===0||lastLetters<0){renderLetters();lastLetters=p.frameCount}p.image(letters,0,0);clock()};
});
